#include "wigle_ca_pem.h"  // generated by `make init`: WIGLE_CA_PEM[]

#define WIGLE_HOST "api.wigle.net"
#define WIGLE_PATH "/api/v2/file/upload"
#define WIGLE_PORT 443

// 60 s for DNS, 30 s for the TLS handshake, 5 min for the body
// transfer (real-world 150 KB over a phone tether is well under this).
#define DNS_TIMEOUT_MS       60000
#define HANDSHAKE_TIMEOUT_MS 30000
#define UPLOAD_TIMEOUT_MS    300000

// ----- base64 (encode only) -----------------------------------------------

static const char b64_chars[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static size_t b64_encode(const unsigned char *in, size_t in_len,
                         char *out, size_t out_cap) {
    size_t need = 4 * ((in_len + 2) / 3) + 1;
    if (out_cap < need) return 0;

    size_t i = 0, j = 0;
    while (i + 2 < in_len) {
        out[j++] = b64_chars[(in[i] >> 2) & 0x3f];
        out[j++] = b64_chars[((in[i] & 0x3) << 4) | (in[i+1] >> 4)];
        out[j++] = b64_chars[((in[i+1] & 0xf) << 2) | (in[i+2] >> 6)];
        out[j++] = b64_chars[in[i+2] & 0x3f];
        i += 3;
    }
    if (i < in_len) {
        out[j++] = b64_chars[(in[i] >> 2) & 0x3f];
        if (i + 1 == in_len) {
            out[j++] = b64_chars[(in[i] & 0x3) << 4];
            out[j++] = '=';
        } else {
            out[j++] = b64_chars[((in[i] & 0x3) << 4) | (in[i+1] >> 4)];
            out[j++] = b64_chars[(in[i+1] & 0xf) << 2];
        }
        out[j++] = '=';
    }
    out[j] = '\0';
    return j;
}

// ----- DNS ----------------------------------------------------------------

static volatile bool   dns_done;
static volatile bool   dns_ok;
static          ip_addr_t dns_addr;

static void dns_cb(const char *name, const ip_addr_t *ipaddr, void *arg) {
    (void)name; (void)arg;
    if (ipaddr) {
        dns_addr = *ipaddr;
        dns_ok = true;
    }
    dns_done = true;
}

static int resolve(const char *host, ip_addr_t *out) {
    dns_done = false;
    dns_ok   = false;
    cyw43_arch_lwip_begin();
    err_t err = dns_gethostbyname(host, &dns_addr, dns_cb, NULL);
    cyw43_arch_lwip_end();

    if (err == ERR_OK) {
        *out = dns_addr;
        return 0;
    }
    if (err != ERR_INPROGRESS) {
        printf("upload: dns immediate err=%d\n", err);
        return -1;
    }

    absolute_time_t deadline = make_timeout_time_ms(DNS_TIMEOUT_MS);
    while (!dns_done) {
        if (absolute_time_diff_us(get_absolute_time(), deadline) <= 0) {
            printf("upload: dns timeout\n");
            return -1;
        }
        sleep_ms(50);
    }
    if (!dns_ok) {
        printf("upload: dns failed\n");
        return -1;
    }
    *out = dns_addr;
    return 0;
}

// ----- TCP/TLS connection state ------------------------------------------

typedef struct {
    volatile bool connected;
    volatile bool closed;
    volatile bool err;
    // Set when lwip's err_cb fires: the pcb is already freed and we
    // must not call altcp_close on it again.
    volatile bool pcb_invalid;

    volatile int  http_status;       // 0 until we parse the status line
    volatile bool headers_done;
    volatile bool resp_complete;

    char  resp_head[256];
    size_t resp_head_len;
} upload_ctx_t;

static err_t conn_cb(void *arg, struct altcp_pcb *pcb, err_t err) {
    upload_ctx_t *ctx = arg;
    (void)pcb;
    if (err != ERR_OK) {
        ctx->err = true;
        ctx->closed = true;
        return ERR_OK;
    }
    ctx->connected = true;
    return ERR_OK;
}

static void err_cb(void *arg, err_t err) {
    upload_ctx_t *ctx = arg;
    printf("upload: lwip err_cb: %d\n", err);
    ctx->err = true;
    ctx->closed = true;
    ctx->pcb_invalid = true;
}

// Parse "HTTP/1.1 200 OK..." once we accumulate the first line. The
// rest of the response body we read but don't store.
static void parse_status_if_ready(upload_ctx_t *ctx) {
    if (ctx->http_status) return;
    char *eol = memchr(ctx->resp_head, '\n', ctx->resp_head_len);
    if (!eol) return;
    // Status line shape: "HTTP/1.1 NNN ...".
    const char *p = ctx->resp_head;
    while (p < eol && *p != ' ') p++;
    if (p < eol) p++;
    ctx->http_status = atoi(p);
}

static err_t recv_cb(void *arg, struct altcp_pcb *pcb,
                     struct pbuf *p, err_t err) {
    upload_ctx_t *ctx = arg;
    (void)pcb;
    if (!p) {
        // Remote closed. The outer cleanup path will free the pcb;
        // calling altcp_close here would risk a double-close because
        // wigle_upload_run also closes on its way out.
        ctx->resp_complete = true;
        ctx->closed = true;
        return ERR_OK;
    }
    if (err != ERR_OK) {
        pbuf_free(p);
        ctx->err = true;
        return err;
    }

    // Capture the head of the response so we can read the status line.
    if (ctx->resp_head_len < sizeof(ctx->resp_head) - 1) {
        size_t cap = sizeof(ctx->resp_head) - 1 - ctx->resp_head_len;
        u16_t copied = pbuf_copy_partial(p,
                                         ctx->resp_head + ctx->resp_head_len,
                                         (u16_t)cap, 0);
        ctx->resp_head_len += copied;
        ctx->resp_head[ctx->resp_head_len] = '\0';
        parse_status_if_ready(ctx);
    }

    altcp_recved(pcb, p->tot_len);
    pbuf_free(p);
    return ERR_OK;
}

// ----- request writing ---------------------------------------------------

static int write_all(struct altcp_pcb *pcb, upload_ctx_t *ctx,
                     const void *data, size_t len) {
    const uint8_t *bytes = data;
    size_t remaining = len;
    absolute_time_t deadline = make_timeout_time_ms(UPLOAD_TIMEOUT_MS);

    while (remaining > 0) {
        if (ctx->err || ctx->closed) return -1;
        if (absolute_time_diff_us(get_absolute_time(), deadline) <= 0) {
            printf("upload: write timeout\n");
            return -1;
        }

        cyw43_arch_lwip_begin();
        u16_t avail = altcp_sndbuf(pcb);
        u16_t want  = remaining < avail ? (u16_t)remaining : avail;
        err_t err = ERR_MEM;
        if (want > 0) {
            err = altcp_write(pcb, bytes, want, TCP_WRITE_FLAG_COPY);
            if (err == ERR_OK) altcp_output(pcb);
        }
        cyw43_arch_lwip_end();

        if (err == ERR_OK) {
            bytes += want;
            remaining -= want;
        } else if (err == ERR_MEM) {
            sleep_ms(20);
        } else {
            printf("upload: altcp_write err=%d\n", err);
            return -1;
        }
    }
    return 0;
}

// Build the multipart envelope. The body sandwich is:
//
//   --B\r\n
//   Content-Disposition: form-data; name="file"; filename="scan.csv"\r\n
//   Content-Type: text/csv\r\n
//   \r\n
//   <csv bytes>
//   \r\n--B--\r\n
//
// We send it as three writes (preamble, csv, trailer) to avoid copying
// the (large) csv payload an extra time.
static const char BOUNDARY[] = "----picow-wigle-9b1f7c8e";

static int send_request(struct altcp_pcb *pcb, upload_ctx_t *ctx,
                        const char *csv, size_t csv_len) {
    char preamble[256];
    int pre_len = snprintf(preamble, sizeof(preamble),
        "--%s\r\n"
        "Content-Disposition: form-data; name=\"file\"; filename=\"scan.csv\"\r\n"
        "Content-Type: text/csv\r\n"
        "\r\n",
        BOUNDARY);
    if (pre_len <= 0 || pre_len >= (int)sizeof(preamble)) return -1;

    char trailer[64];
    int trail_len = snprintf(trailer, sizeof(trailer),
        "\r\n--%s--\r\n", BOUNDARY);
    if (trail_len <= 0 || trail_len >= (int)sizeof(trailer)) return -1;

    size_t body_len = (size_t)pre_len + csv_len + (size_t)trail_len;

    // Authorization: Basic base64(api_name:api_token).
    char ident[256];
    int ident_len = snprintf(ident, sizeof(ident), "%s:%s",
                             WIGLE_API_NAME, WIGLE_API_TOKEN);
    if (ident_len <= 0 || ident_len >= (int)sizeof(ident)) return -1;

    char b64_auth[384];
    if (b64_encode((const unsigned char *)ident, (size_t)ident_len,
                   b64_auth, sizeof(b64_auth)) == 0) {
        return -1;
    }

    char headers[1024];
    int hdr_len = snprintf(headers, sizeof(headers),
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "User-Agent: pico2w-wigle/1.0\r\n"
        "Authorization: Basic %s\r\n"
        "Accept: application/json\r\n"
        "Content-Type: multipart/form-data; boundary=%s\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n",
        WIGLE_PATH, WIGLE_HOST, b64_auth, BOUNDARY, body_len);
    if (hdr_len <= 0 || hdr_len >= (int)sizeof(headers)) return -1;

    if (write_all(pcb, ctx, headers,  (size_t)hdr_len)   < 0) return -1;
    if (write_all(pcb, ctx, preamble, (size_t)pre_len)   < 0) return -1;
    if (write_all(pcb, ctx, csv,      csv_len)           < 0) return -1;
    if (write_all(pcb, ctx, trailer,  (size_t)trail_len) < 0) return -1;
    return 0;
}

// ----- entry point -------------------------------------------------------

static int connect_upload_wifi(void) {
    printf("upload: associating with \"%s\"...\n", UPLOAD_WIFI_SSID);
    int err = cyw43_arch_wifi_connect_timeout_ms(
        UPLOAD_WIFI_SSID,
        UPLOAD_WIFI_PASSWORD,
        CYW43_AUTH_WPA2_AES_PSK,
        30000);
    if (err) {
        printf("upload: wifi connect failed: %d\n", err);
        return -1;
    }
    return 0;
}

static void disconnect_upload_wifi(void) {
    cyw43_wifi_leave(&cyw43_state, CYW43_ITF_STA);
}

int wigle_upload_run(const char *csv, size_t csv_len) {
    if (!csv || csv_len == 0) return -1;

    if (connect_upload_wifi() != 0) return -1;

    int rc = -1;
    struct altcp_tls_config *tls_conf = NULL;
    struct altcp_pcb *pcb = NULL;
    upload_ctx_t ctx = {0};

    ip_addr_t addr;
    if (resolve(WIGLE_HOST, &addr) != 0) goto out;

    // ISRG Root X1 (+ X2 when available), extracted from the build
    // host's CA store at `make init` time. Passing a non-empty CA
    // makes lwIP's altcp_tls_mbedtls layer set
    // MBEDTLS_SSL_VERIFY_REQUIRED, so the handshake fails unless the
    // server's chain roots in one of these. Length must include the
    // trailing NUL byte — sizeof() of a string-literal-initialised
    // array gives us that for free.
    tls_conf = altcp_tls_create_config_client(WIGLE_CA_PEM,
                                              sizeof(WIGLE_CA_PEM));
    if (!tls_conf) {
        printf("upload: tls config alloc failed (bad CA bundle?)\n");
        goto out;
    }

    cyw43_arch_lwip_begin();
    pcb = altcp_tls_new(tls_conf, IPADDR_TYPE_V4);
    if (pcb) {
        altcp_arg(pcb, &ctx);
        altcp_recv(pcb, recv_cb);
        altcp_err(pcb, err_cb);
        // SNI for virtual-hosted servers. Without this the cert
        // presented may not match and the handshake fails.
        mbedtls_ssl_context *ssl =
            (mbedtls_ssl_context *)altcp_tls_context(pcb);
        if (ssl) mbedtls_ssl_set_hostname(ssl, WIGLE_HOST);
    }
    err_t err = pcb ? altcp_connect(pcb, &addr, WIGLE_PORT, conn_cb) : ERR_MEM;
    cyw43_arch_lwip_end();
    if (!pcb || err != ERR_OK) {
        printf("upload: altcp_connect err=%d\n", err);
        goto out;
    }

    absolute_time_t deadline = make_timeout_time_ms(HANDSHAKE_TIMEOUT_MS);
    while (!ctx.connected && !ctx.err) {
        if (absolute_time_diff_us(get_absolute_time(), deadline) <= 0) {
            printf("upload: handshake timeout\n");
            goto out;
        }
        sleep_ms(50);
    }
    if (ctx.err) goto out;

    // If the server closes the connection early (typical for 401)
    // write_all bails; that's not necessarily fatal for diagnostics —
    // we still want to read whatever status line came back before
    // giving up.
    (void)send_request(pcb, &ctx, csv, csv_len);

    deadline = make_timeout_time_ms(UPLOAD_TIMEOUT_MS);
    while (!ctx.closed && !ctx.err) {
        if (absolute_time_diff_us(get_absolute_time(), deadline) <= 0) {
            printf("upload: response timeout\n");
            goto out;
        }
        sleep_ms(50);
    }

    if (ctx.http_status >= 200 && ctx.http_status < 300) {
        printf("upload: HTTP %d ok\n", ctx.http_status);
        rc = 0;
    } else {
        printf("upload: HTTP %d (head: %.*s)\n",
               ctx.http_status,
               (int)(ctx.resp_head_len > 80 ? 80 : ctx.resp_head_len),
               ctx.resp_head);
    }

out:
    if (pcb && !ctx.pcb_invalid) {
        cyw43_arch_lwip_begin();
        altcp_close(pcb);
        cyw43_arch_lwip_end();
    }
    if (tls_conf) altcp_tls_free_config(tls_conf);
    disconnect_upload_wifi();
    return rc;
}
